/* telc B1 Schreiben: the 18 writing tasks of the book "Prüfungs Buch Petra" (letter, 4 points, instructions). Built by build_ref_pages.py */
window.TELC_SCHREIBEN = [{"no":1,"title":"Petra","intro":"Eine Bekannte hat Ihnen folgenden Brief geschrieben:","letter":["Liebe(r) …,","Ich habe eine tolle Überraschung. stelle dir vor, was mir mein Onkel angeboten hat. Er rief mich am Samstag an. Er hat ein großes Ferienhaus im Schwarzwald. Das Haus kann ich für die Ferien kostenlos haben. Ich kann auch Freunde mitbringen! Wäre das nichts für uns? Wir könnten uns alle dort treffen. Du, deine Eltern und Freunde, und ich mit meiner Familie und meinen Freunden. Ich würde mich wahnsinnig freuen, wenn das klappen würde. Bitte schreibe mir so schnell du kannst, damit wir alles planen können. Urlaub im Schwarzwald - das wird traumhaft schön!","Herzliche Grüße Petra"],"task":"Antworten Sie auf den Brief. Schreiben Sie etwas zu den folgenden Punkten:","points":["Warum Sie gern nach Deutschland kommen möchten","Wie Sie anreisen wollen","Was Sie gemeinsam machen könnten","Wen Sie mitbringen möchten"],"hints":"Bevor Sie den Brief schreiben, überlegen Sie sich eine passende Reihenfolge der punkte, eine passende Einleitung und einen passenden Schluss. Vergessen Sie nicht Datum und Anrede. Schreiben Sie mindestens 100 Wörter.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Petra,</strong>","tag":"Shell · Anrede","en":"Dear Petra,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Was für eine tolle Nachricht! Ich freue mich sehr für dich.</strong>","tag":"template, exact, kind 2 (React)","en":"What great news! I am very happy for you."},{"de":"Ein Ferienhaus im Schwarzwald ist wirklich toll.","tag":"own words","en":"A holiday house in the Black Forest is really great."},{"de":"<strong>Ich komme sehr gern, weil ich dich lange nicht gesehen habe.</strong>","tag":"template, exact, kind 2 (React) · P1","en":"I would love to come, because I have not seen you for a long time."},{"de":"Außerdem möchte ich Deutschland endlich besser kennenlernen. Im Schwarzwald war ich noch nie.","tag":"own words · P1","en":"Also, I finally want to get to know Germany better. I have never been to the Black Forest."},{"de":"<strong>Ich komme mit dem Zug. Kannst du mich vom Bahnhof abholen?</strong>","tag":"template, exact, kind 7 (How to travel) · P2","en":"I am coming by train. Can you pick me up from the station?"},{"de":"<strong>Wie wäre es, wenn wir</strong> jeden Tag im Wald wandern? <strong>Wir könnten</strong> abends zusammen grillen.","tag":"template, start only, kind 3 (Suggest a meeting) · P3","en":"How about if we go hiking in the forest every day? We could have a barbecue together in the evening."},{"de":"An einem Tag könnten wir auch an einen See fahren.","tag":"own words · P3","en":"One day we could also go to a lake."},{"de":"<strong>Darf ich meine Frau mitbringen? Sie möchte dich auch gern kennenlernen.</strong>","tag":"template, exact, kind 8 (Bring someone) · P4","en":"May I bring my wife? She would also like to meet you."},{"de":"Ich freue mich schon sehr auf den Urlaub mit euch.","tag":"own words","en":"I am really looking forward to the holiday with you."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":2,"title":"Eva","intro":"Eine Bekannte aus der Schweiz hat eine neue Stelle. Sie hat Ihnen den folgenden Brief geschrieben:","letter":["Liebe(r) …,","wie geht es denn so mit dem Deutsch lernen? Kommst du gut voran, und was machst du im Moment so? Stell dir vor, ich habe die neue Stelle bei der Zeitschrift VIA bekommen! ich arbeite jetzt als Journalistin, und das war ja immer mein Traumberuf!","VIA wird vor allem von jüngeren Leuten gelesen. Deshalb schreiben wir viel über Berufe und Ausbildungen und auch über Freizeit und Sport. Für die nächsten Hefte von VIA planen wir jetzt eine neue Serie über Berufs wünsche. Was ist eigentlich dein Traumberuf? Wenn du möchtest, schicke ich dir gerne einmal ein Grätschet von VIA, damit du siehst, was ich so mache.","Ich freue mich schon auf deine Antwort.","Herzliche Grüße Eva"],"task":"Schreiben Sie Ihrer Bekannten nun einen Antwortbrief, der die folgenden Punkte erhält:","points":["Fortschritte beim Deutsch Lernen","Auf Evas neue Stelle reagieren","Was es Neues bei Ihnen gibt","Ihr Traumberuf"],"hints":"Bevor Sie den Brief schreiben, überlegen Sie sich eine passende Reihenfolge der punkte, eine passende Einleitung und einen passenden Schluss. Vergessen Sie nicht Datum und Anrede.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Eva,</strong>","tag":"Shell · Anrede","en":"Dear Eva,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Was für eine tolle Nachricht! Ich freue mich sehr für dich.</strong>","tag":"template, exact, kind 2 (React) · P2","en":"What great news! I am very happy for you."},{"de":"<strong>Schön, dass du jetzt als Journalistin bei VIA arbeitest.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that you now work as a journalist at VIA."},{"de":"<strong>Bei mir gibt es Neuigkeiten: Ich lerne jetzt Deutsch, weil ich bald eine Prüfung mache.</strong>","tag":"template, exact, kind 5 (Your news) · P3","en":"I have news: I am learning German now, because I have an exam soon."},{"de":"Mit dem Deutschlernen komme ich gut voran. Ich lerne jeden Tag eine Stunde und verstehe schon viel mehr. Nur die Grammatik finde ich noch schwierig.","tag":"own words · P1","en":"I am making good progress with German. I study for an hour every day and already understand much more. Only grammar is still hard for me."},{"de":"<strong>Zurzeit arbeite ich als Softwareentwickler, und meine Wohnung liegt sehr zentral.</strong>","tag":"template, exact, kind 1 (About you) · P4","en":"At the moment I work as a software developer, and my flat is very central."},{"de":"Eigentlich ist das mein Traumberuf, weil ich gern mit Computern arbeite. Später möchte ich vielleicht eine eigene Firma haben.","tag":"own words · P4","en":"Actually that is my dream job, because I like working with computers. Later I would maybe like to have my own company."},{"de":"Schick mir bitte ein Heft von VIA. Ich bin sehr gespannt auf deine Artikel.","tag":"own words · answers her offer","en":"Please send me a copy of VIA. I am very curious about your articles."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":3,"title":"Sophie","intro":"Sie haben folgende E-Mail von Ihrer Freundin Sophie bekommen:","letter":["Liebe(r) …,","wir haben lange nichts mehr voreinander gehört. Ich hoffe, es geht dir gut. Gibt es bei dir Neuigkeiten? Ich bin nun schon seit zwei Monaten in Würzburg, und mein neuer Job gefällt mir sehr gut. In der Firma fühle ich mich wohl, mit meinen Kollegen verstehe ich mich prima und die Arbeit macht mir großen Spaß.","Allerdings habe ich ein Problem: Außer meinen Kollegen kenne ich hier in der Stadt noch niemanden. In meiner Freizeit bin ich oft allein und weiß nicht, was ich machen soll. Wie könnte ich neue Leute kennenlernen? Hast du vielleicht einen Tipp für mich?","Würzburg ist wirklich eine schöne Stadt mit vielen Sehenswürdigkeiten. Hast du Lust, mich mal an einem Wochenende zu besuchen? Ich würde mich sehr freuen.","Viele Grüße Sophie"],"task":"Antworten Sie Sophie. Schreiben Sie etwas zu allen vier Punkten:","points":["Was es Neues bei Ihnen gibt","Was Sie selbst gerne in Ihrer Freizeit machen","Tipps für Sophie","Reaktion auf den Vorschlag"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Sophie,</strong>","tag":"Shell · Anrede","en":"Dear Sophie,"},{"de":"<strong>vielen Dank für deine E-Mail. Ich habe mich sehr gefreut.</strong>","tag":"template, adapted · Brief → E-Mail","en":"Many thanks for your e-mail. I was very happy."},{"de":"<strong>Schön, dass dir dein neuer Job in Würzburg so gut gefällt.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that you like your new job in Würzburg so much."},{"de":"<strong>Bei mir gibt es Neuigkeiten: Ich lerne jetzt Deutsch, weil ich bald eine Prüfung mache.</strong>","tag":"template, exact, kind 5 (Your news) · P1","en":"I have news: I am learning German now, because I have an exam soon."},{"de":"<strong>Am Wochenende koche ich gern für meine Familie.</strong>","tag":"template, exact, kind 1 (About you) · P2","en":"At the weekend I like cooking for my family."},{"de":"Außerdem gehe ich oft im Park spazieren. Dort treffe ich oft meine Nachbarn.","tag":"own words · P2","en":"Also, I often go for walks in the park. I often meet my neighbours there."},{"de":"<strong>Ich schlage vor, dass du einem Verein beitrittst. Dort lernst du schnell neue Leute kennen.</strong>","tag":"template, exact, kind 4 (Give a tip) · P3","en":"I suggest that you join a club. There you will quickly get to know new people."},{"de":"Du könntest auch einen Sportkurs machen. In einem Kurs findest du schnell Freunde.","tag":"own words · P3 · second tip","en":"You could also take a sports course. In a course you quickly find friends."},{"de":"<strong>Ich komme sehr gern, weil ich dich lange nicht gesehen habe.</strong>","tag":"template, exact, kind 2 (React) · P4","en":"I would love to come, because I have not seen you for a long time."},{"de":"Passt dir das Wochenende in zwei Wochen? Dann können wir zusammen die Stadt ansehen.","tag":"own words · P4 · when","en":"Does the weekend in two weeks suit you? Then we can look at the city together."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":4,"title":"Nadja","intro":"Sie haben von einer Freundin folgenden Brief erhalten:","letter":["Liebe(r) …,","ich hoffe, dir geht’s gut. stell dir vor, bei mir gibt es Neuigkeiten Du weißt doch, dass wir schon lange von einem Garten geträumt haben. Jetzt haben wir endlich einen am Stadtrand gefunden. Da er sehr groß ist. Wollte ich dich fragen, ob du nicht Lust hast den Garten mit uns zu teilen.","Die Miete ist gar nicht so hoch . Du könntest dort Salat und Gemüse anpflanzen, natürlich auch Blumen ganz wie du willst. Es gibt auch Obstbäume und eine große Wiese, auf der man sich einfach hinlegen, und wir könnten im Garten auch grillen. Was denkst du? Wäre das nicht toll.","Antworte mir bald.","Alles Liebe Deine Nadja"],"task":"Antworten Sie auf den Brief. Schreiben Sie etwas zu den folgenden vier Punkten:","points":["Reaktion auf den Vorschlag","Fragen zum Garten","Weg zum Garten","Was es bei Ihnen Neues gibt"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Nadja,</strong>","tag":"Shell · Anrede","en":"Dear Nadja,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Was für eine tolle Nachricht! Ich freue mich sehr für dich.</strong>","tag":"template, exact, kind 2 (React) · P1","en":"What great news! I am very happy for you."},{"de":"Ich teile den Garten sehr gern mit euch, weil ich gern draußen bin. Ich möchte dort Tomaten und Blumen anpflanzen.","tag":"own words · P1 · say yes","en":"I would love to share the garden with you, because I like being outside. I would like to plant tomatoes and flowers there."},{"de":"Ich habe aber noch ein paar Fragen: Wie hoch ist die Miete genau? Gibt es im Garten Wasser und eine kleine Hütte?","tag":"own words · P2 · own questions","en":"But I still have a few questions: how high is the rent exactly? Is there water and a small hut in the garden?"},{"de":"<strong>Ich komme mit dem Zug. Kannst du mich vom Bahnhof abholen?</strong>","tag":"template, exact, kind 7 (How to travel) · P3","en":"I am coming by train. Can you pick me up from the station?"},{"de":"Oder fährt vom Bahnhof ein Bus zum Garten?","tag":"own words · P3","en":"Or does a bus go from the station to the garden?"},{"de":"<strong>Bei mir gibt es Neuigkeiten: Ich lerne jetzt Deutsch, weil ich bald eine Prüfung mache.</strong>","tag":"template, exact, kind 5 (Your news) · P4","en":"I have news: I am learning German now, because I have an exam soon."},{"de":"Ich lerne jeden Tag eine Stunde. Nach der Prüfung habe ich mehr Zeit für den Garten.","tag":"own words · P4","en":"I study for an hour every day. After the exam I will have more time for the garden."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":5,"title":"Nicole","intro":"Eine Freundin beschreibt in einem Brief, welche Probleme sie mit ihrem Bruder hat und bittet Sie um Rat:","letter":["Liebe(r) …,","entschuldige, dass ich dir so lange nicht mehr geschrieben habe. Aber weißt du, mein älterer Bruder, der schon lange im Ausland lebt, ist jetzt für zwei Monate bei uns. Wir unternehmen einiges zusammen, z. B. gehen wir nachmittags ins Schwimmbad oder abends ins Kino. Wir verstehen uns eigentlich ganz gut, aber dennoch habe ich ein Problem mit ihm: Wenn es im Fernsehen Sportsendungen gibt, dann bekomme ich ihn nicht mehr weg vom Fernseher! Er sitzt dann stundenlang nur da und sieht fern, ganz egal, wie schön das Wetter draußen ist! Was soll ich bloß tun? Überhaupt nichts sagen oder soll ich mit ihm deswegen streiten? Er fährt bald wieder weg und ich möchte doch mit ihm zusammen sein. Was würdest du machen? Hast du vielleicht ein paar Tipps oder Ratschläge für mich?","Herzliche Grüße, Nicole"],"task":"Schreiben Sie Ihrer Bekannten einen Antwortbrief, der die folgenden Punkte enthält:","points":["Eigene Erfahrungen mit Geschwistern, Freunden, …","Tipps für Nicole","Was Sie über den Bruder denken","Was Sie selbst gern gemeinsam mit anderen machen"],"hints":"Bevor Sie den Brief schreiben, überlegen Sie sich eine passende Reihenfolge der Punkte, einen passenden Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Nicole,</strong>","tag":"Shell · Anrede","en":"Dear Nicole,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Schön, dass dein Bruder für zwei Monate bei euch ist.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that your brother is staying with you for two months."},{"de":"Dein Problem kenne ich gut. Meine Freunde in Pakistan sitzen auch stundenlang vor dem Fernseher, wenn es Cricket gibt. Früher habe ich mich darüber oft geärgert.","tag":"own words · P1","en":"I know your problem well. My friends in Pakistan also sit in front of the TV for hours when there is cricket. I often used to get annoyed about it."},{"de":"Ich glaube, dein Bruder ist nicht böse. Er liebt Sport einfach sehr, und im Ausland kann er die Spiele vielleicht nicht sehen.","tag":"own words · P3","en":"I think your brother does not mean any harm. He just loves sport very much, and abroad he maybe cannot watch the games."},{"de":"<strong>An deiner Stelle würde ich mit deinem Bruder sprechen.</strong>","tag":"template, adapted, kind 4 (Give a tip) · P2 · dem Nachbarn → deinem Bruder","en":"If I were you, I would talk to your brother."},{"de":"Streite aber nicht mit ihm. Schaut die wichtigen Spiele zusammen an, und danach geht ihr ins Schwimmbad.","tag":"own words · P2","en":"But do not argue with him. Watch the important games together, and after that you go to the swimming pool."},{"de":"<strong>Am Wochenende koche ich gern für meine Familie.</strong>","tag":"template, exact, kind 1 (About you) · P4","en":"At the weekend I like cooking for my family."},{"de":"Danach essen wir alle zusammen, und manchmal spielen wir mit Freunden Cricket im Park.","tag":"own words · P4","en":"After that we all eat together, and sometimes we play cricket with friends in the park."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":6,"title":"Andreas","intro":"Sie haben im Urlaub Andreas kennengelernt. Er hat Ihnen folgende E-Mail geschrieben:","letter":["Liebe(r) …,","heute habe ich Zeit, dir ein paar Zeilen zu schreiben. Der Urlaub war so schön, aber seit ich zurück bin, habe ich im Büro sehr viel Arbeit. Bestimmt brauche ich schon bald wieder Urlaub! Während ich weg war, hat sich hier übrigens einiges geändert: Es gibt einen neuen Kollegen, er heißt Roberto. Was aber die größte Veränderung ist: Er arbeitet mit mir in meinem Büro, das heißt, ich habe endlich jemanden, mit dem ich mich zwischendurch auch ein bisschen unterhalten kann! Roberto ist aus Spanien hierher gezogen. Er kennt noch niemanden hier, außer mir natürlich, und ist meistens allein. Denkst du, dass ich ihn und ein paar andere Arbeitskollegen einmal einladen sollte? Was würdest du tun? Na gut, für heute muss ich Schluss machen. Melde dich doch bald einmal bei mir!","Viele Grüße, Andreas"],"task":"Antworten Sie Andreas. Schreiben Sie etwas zu allen vier Punkten:","points":["Vorschlag, wie Andreas seinem Arbeitskollegen helfen kann","Wie Sie am liebsten arbeiten (alleine oder mit Kollegen)","Was Sie nach dem Urlaub gemacht haben","Was es bei Ihnen Neues gibt"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der Punkte, einen passenden Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Lieber Andreas,</strong>","tag":"Shell · Anrede","en":"Dear Andreas,"},{"de":"<strong>vielen Dank für deine E-Mail. Ich habe mich sehr gefreut.</strong>","tag":"template, adapted · Brief → E-Mail","en":"Many thanks for your e-mail. I was very happy."},{"de":"<strong>Schön, dass du jetzt einen netten Kollegen in deinem Büro hast.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that you now have a nice colleague in your office."},{"de":"Lade Roberto und ein paar Kollegen ruhig einmal zu dir nach Hause ein. Darüber freut er sich bestimmt.","tag":"own words · P1","en":"Do invite Roberto and a few colleagues to your home some time. He will surely be happy about that."},{"de":"<strong>Ich schlage vor, dass Roberto einem Verein beitritt. Dort lernt er schnell neue Leute kennen.</strong>","tag":"template, adapted, kind 4 (Give a tip) · P1 · du → Roberto","en":"I suggest that Roberto joins a club. There he will quickly get to know new people."},{"de":"<strong>Zurzeit arbeite ich als Softwareentwickler, und meine Wohnung liegt sehr zentral.</strong>","tag":"template, exact, kind 1 (About you) · P2","en":"At the moment I work as a software developer, and my flat is very central."},{"de":"Am liebsten arbeite ich mit Kollegen zusammen, weil wir Probleme dann schneller lösen. Nur für schwierige Aufgaben brauche ich Ruhe.","tag":"own words · P2","en":"I like working with colleagues best, because then we solve problems faster. Only for difficult tasks do I need quiet."},{"de":"Nach dem Urlaub hatte ich auch sehr viel Arbeit. Am ersten Wochenende war ich aber mit meiner Frau in den Bergen.","tag":"own words · P3","en":"After the holiday I also had a lot of work. But on the first weekend I was in the mountains with my wife."},{"de":"<strong>Bei mir gibt es Neuigkeiten: Ich lerne jetzt Deutsch, weil ich bald eine Prüfung mache.</strong>","tag":"template, exact, kind 5 (Your news) · P4","en":"I have news: I am learning German now, because I have an exam soon."},{"de":"Ich lerne jeden Abend nach der Arbeit eine Stunde.","tag":"own words · P4","en":"I study for an hour every evening after work."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":7,"title":"Annika","intro":"Sie haben von einer Freundin folgenden Brief erhalten:","letter":["Liebe(r) …,","Wie geht’s dir? Hattest du ein schönes Wochenende? Hier hat es die ganze Zeit geregnet, deshalb bin ich zuhause geblieben.","Du hattest vorgeschlagen, dass wir im Sommer zusammen verreisen könnten. Die Idee finde ich super! An welches Reiseziel denkst du? Ich bin gerne am Meer, mag aber auch Städterreisen. Wichtig ist für mich nur, dass ich auch ein bisschen Sport machen kann. Die Reise sollte aber nicht zu viel kosten, denn ich habe vor Kurzem schon viel für eine Autoreparatur bezahlen müssen. Was meinst du: wie können wir günstig Urlaub machen? Es muss ja kein Luxushotel sein.","Schreib mir bald, dann können wir anfangen zu planen.","Viele Grüße Annika"],"task":"Antworten Sie Annika. Schreiben Sie etwas zu allen vier Punkten:","points":["Was Sie am Wochenende unternommen haben","Wohin Sie gerne reisen würden","Was Sie im Urlaub gerne machen","Wie man beim Reisen Geld sparen kann"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Annika,</strong>","tag":"Shell · Anrede","en":"Dear Annika,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Es tut mir leid, dass es bei dir das ganze Wochenende geregnet hat.</strong>","tag":"Shell · Es tut mir leid, dass …","en":"I am sorry that it rained the whole weekend where you are."},{"de":"<strong>Am Wochenende koche ich gern für meine Familie.</strong>","tag":"template, exact, kind 1 (About you) · P1","en":"At the weekend I like cooking for my family."},{"de":"Am Samstag habe ich für meine Eltern gekocht, und am Sonntag war ich mit meiner Frau in den Bergen.","tag":"own words · P1","en":"On Saturday I cooked for my parents, and on Sunday I was in the mountains with my wife."},{"de":"Deine Idee finde ich auch super! Ich würde gern ans Meer fahren, zum Beispiel nach Italien.","tag":"own words · P2","en":"I also think your idea is great! I would like to go to the sea, for example to Italy."},{"de":"Im Urlaub schwimme ich gern und spiele Volleyball am Strand. Abends sehe ich mir gern die Stadt an.","tag":"own words · P3","en":"On holiday I like swimming and playing volleyball on the beach. In the evening I like looking around the town."},{"de":"<strong>Ich schlage vor, dass</strong> wir mit dem Zug fahren und eine kleine Ferienwohnung mieten.","tag":"template, start only, kind 4 (Give a tip) · P4","en":"I suggest that we go by train and rent a small holiday flat."},{"de":"Dort können wir selbst kochen. Das ist viel billiger als ein Hotel.","tag":"own words · P4","en":"There we can cook ourselves. That is much cheaper than a hotel."},{"de":"<strong>Wie wäre es, wenn wir uns am Samstag treffen?</strong> Dann planen wir alles zusammen.","tag":"template, start only, kind 3 (Suggest a meeting) · first sentence exact","en":"How about if we meet on Saturday? Then we plan everything together."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":8,"title":"Iris","intro":"Eine Bekannte hat Ihnen den folgende E-Mail geschrieben:","letter":["Liebe(r) …,","endlich habe ich die Deutscheprüfung hinter mir. Ich glaube, es ist gut gelaufen. Jetzt soll für unseren Kurs eine Party organisieren. Du hast doch kürzlich erzählt, dass Du für Euren Kurs auch ein Abschlussfest organsiert hast. Sicher kannst du mir ein paar Tipps geben. Ich habe mir gedacht, wir könnten vielleicht in einem Restaurant feiern .Da kann jeder essen und trinken, was er will . Was meinst Du? Essen zu kochen ist doch ziemlich viel Arbeit. und natürlich brauchen wir Musik. Welche Musik ist am besten geeignet? Was schlägst Du vor? Melde Dich bald.","Ich freue mich schon auf deine Antwort.","Liebe Grüße Iris"],"task":"Antworten Sie Ihrer Bekannten. Schreiben Sie etwas zu allen vier Punkten:","points":["Reaktion auf die Prüfung","Wo feiern? Restaurant- Ihre Meinung","Welche Musik","Urlaubpläne"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Iris,</strong>","tag":"Shell · Anrede","en":"Dear Iris,"},{"de":"<strong>vielen Dank für deine E-Mail. Ich habe mich sehr gefreut.</strong>","tag":"template, adapted · Brief → E-Mail","en":"Many thanks for your e-mail. I was very happy."},{"de":"<strong>Was für eine tolle Nachricht! Ich freue mich sehr für dich.</strong>","tag":"template, exact, kind 2 (React) · P1","en":"What great news! I am very happy for you."},{"de":"<strong>Schön, dass die Prüfung gut gelaufen ist.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that the exam went well."},{"de":"Ein Restaurant finde ich eine gute Idee, weil dann niemand kochen muss. Unser Abschlussfest war auch in einem Restaurant, und es war sehr schön.","tag":"own words · P2","en":"I think a restaurant is a good idea, because then nobody has to cook. Our end-of-course party was in a restaurant too, and it was very nice."},{"de":"<strong>An deiner Stelle würde ich</strong> im Restaurant einen Raum für den ganzen Kurs reservieren.","tag":"template, start only, kind 4 (Give a tip) · P2","en":"If I were you, I would book a room for the whole course in the restaurant."},{"de":"<strong>Ich schlage vor, dass</strong> ihr Musik aus allen Ländern im Kurs spielt. Dann kann jeder ein Lied mitbringen.","tag":"template, start only, kind 4 (Give a tip) · P3","en":"I suggest that you play music from all the countries in the course. Then everyone can bring a song."},{"de":"<strong>Zurzeit arbeite ich als Softwareentwickler, und meine Wohnung liegt sehr zentral.</strong>","tag":"template, exact, kind 1 (About you) · P4","en":"At the moment I work as a software developer, and my flat is very central."},{"de":"Im Sommer habe ich drei Wochen Urlaub. Dann fliege ich mit meiner Frau nach Pakistan und besuche meine Familie.","tag":"own words · P4","en":"In the summer I have three weeks of holiday. Then I will fly to Pakistan with my wife and visit my family."},{"de":"Ich wünsche euch viel Spaß auf der Party!","tag":"own words","en":"I wish you lots of fun at the party!"},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":9,"title":"Sonja","intro":"Sie haben von einer Freundin folgenden Brief erhalten:","letter":["Liebe(r) …,","die Sommerferien kommen rasch näher und ich freue mich sehr, dass du mich besuchen kommst. Ich habe eine tolle Idee: Ich möchte dich gerne zu einem Musikfestival einladen, und zwar nach Rüdesheim (ca. 50 km von Mainz). Dort spielen in diesem Sommer die besten internationalen Musikgruppen. Ich finde Open-Air-Konzerte einfach toll: die friedliche Stimmung unter den Besuchern, die gute Musik und einfach viele schöne Momente, die man nie mehr vergisst. Vor allem, wenn das Wetter gut ist, kann man das so richtig genießen. Wir könnten mit dem Zug nach Rüdesheim fahren oder auch mein Auto nehmen. Was wäre dir lieber? Übernachten würde ich gern auf dem Festplatz. Was meinst du? Und willst du vielleicht noch jemanden mitbringen? Vielleicht hast du noch einen Wunsch, was du sonst noch hier machen möchtest? Schreibe mir bitte möglichst bald. Ich freue mich schon auf deine Antwort.","Herzliche Grüße, Sonja"],"task":"Antworten Sie Sonja. Schreiben Sie in Ihrem Brief etwas zu allen vier Punkten:","points":["Was sonst noch machen?","Wie zum Festival reisen?","Jemanden mitbringen?","Übernachten: Reaktion auf Sonjas Vorschlag"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der Punkte, einen passenden Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Sonja,</strong>","tag":"Shell · Anrede","en":"Dear Sonja,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Schön, dass</strong> du mich zu einem Musikfestival einlädst.","tag":"Shell · Schön, dass … · P4","en":"It is nice that you invite me to a music festival."},{"de":"<strong>Ich komme sehr gern, weil ich dich lange nicht gesehen habe.</strong>","tag":"template, exact, kind 2 (React) · P4","en":"I would love to come, because I have not seen you for a long time."},{"de":"<strong>Ich schlage vor, dass</strong> wir mit dem Zug nach Rüdesheim fahren. Das ist billiger, und wir müssen keinen Parkplatz suchen.","tag":"Shell · Ich schlage vor, dass … · P2","en":"I suggest that we go to Rüdesheim by train. It is cheaper, and we do not have to look for a parking space."},{"de":"Auf dem Festplatz zu übernachten, finde ich eine gute Idee. Leider habe ich kein Zelt. <strong>Kannst du bitte</strong> eines mitbringen?","tag":"own words + Shell · Kannst du bitte …? · P4","en":"I think it is a good idea to stay overnight at the festival site. Unfortunately I have no tent. Could you please bring one?"},{"de":"<strong>Wie wäre es, wenn wir</strong> am Tag vorher in Mainz die Stadt ansehen? Wir könnten auch am Rhein spazieren gehen.","tag":"template start + own words · kind 3 (Suggest) · P1","en":"How about we look at the city of Mainz the day before? We could also go for a walk along the Rhine."},{"de":"<strong>Darf ich meine Frau mitbringen? Sie möchte dich auch gern kennenlernen.</strong>","tag":"template, exact, kind 8 · P3","en":"May I bring my wife? She would also like to get to know you."},{"de":"Ich freue mich schon sehr auf die Musik und die gute Stimmung.","tag":"own words · closing thought","en":"I am already looking forward to the music and the good atmosphere."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":10,"title":"Carolina","intro":"Sie haben von einer Bekannten folgenden E-Mail erhalten:","letter":["Liebe(r) …,","Du hast schon so lange nicht mehr geschrieben. Wie geht es dir? Heute habe ich eine Bitte. Vielleicht kannst du uns helfen?","Eine 16-jährige Schülerin aus deinem Land wird uns besuchen und zwei Wochen bei uns in Goldbach bleiben. Natürlich möchten wir, dass sie sich wohl fühlt. Dein Land kennen wir nur von deinen Erzählungen, denn wir waren selbst noch nicht da. Bitte gib uns ein paar Informationen Z.B über typische Gewohnheiten oder typisches Essen. Was können wir tun und wie können wir uns vorbereiten?","Wir freuen uns schon auf deine Antwort.","Schon einmal viele Dank und liebe Grüße Caroline"],"task":"Antworten Sie Caroline. Schreiben Sie etwas zu den folgenden vier Punkten:","points":["Reaktion auf den Besuch der Schülerin","Vorschlag zu Essen und Trinken","Warum Sie so lange nicht geschrieben haben","Unternehmungen/Programm mit der Schülerin"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Caroline,</strong>","tag":"Shell · Anrede","en":"Dear Caroline,"},{"de":"<strong>vielen Dank für deine E-Mail. Ich habe mich sehr gefreut.</strong>","tag":"template, adapted · Brief → E-Mail","en":"Many thanks for your e-mail. I was very happy."},{"de":"<strong>Es tut mir leid, dass ich so lange nicht geschrieben habe. Ich hatte sehr viel Arbeit.</strong>","tag":"template, exact, kind 9 (Apologise) · P3","en":"I am sorry that I have not written for so long. I had a lot of work."},{"de":"<strong>Was für eine tolle Nachricht!</strong>","tag":"template, start only, kind 2 (React) · P1","en":"What great news!"},{"de":"<strong>Schön, dass eine Schülerin aus meinem Land zu euch kommt.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that a schoolgirl from my country is coming to you."},{"de":"<strong>An deiner Stelle würde ich</strong> oft Reis mit Gemüse kochen. In meinem Land essen wir sehr gern Reis und trinken viel Tee.","tag":"template, start only, kind 4 (Give a tip) · P2","en":"If I were you, I would often cook rice with vegetables. In my country we really like eating rice and we drink a lot of tea."},{"de":"Fragt sie am besten selbst, was sie gern isst.","tag":"own words · P2","en":"Best ask her yourselves what she likes to eat."},{"de":"<strong>Ich komme euch gern besuchen. Wie wäre es, wenn wir uns am Samstag treffen? Wir könnten zusammen ins Kino gehen.</strong>","tag":"template, exact, kind 3 (Suggest a meeting) · P4","en":"I would like to visit you. How about if we meet on Saturday? We could go to the cinema together."},{"de":"Am Sonntag könnt ihr mit ihr nach Frankfurt fahren. Dort könnt ihr ins Museum gehen und am Main spazieren.","tag":"own words · P4 · programme","en":"On Sunday you can go to Frankfurt with her. There you can go to a museum and walk along the river Main."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":11,"title":"Vera","intro":"Eine Freundin hat Ihnen den folgenden Brief geschrieben:","letter":["Liebe(r) …,","Wie geht es dir und deiner Familie?","Bei mir läuft alles prima. Endlich habe ich eine neue Arbeitsstelle. Ich habe nur ein kleines Problem: Es ist ein bisschen zu weit, um zu Fuß zu gehen.","Und der Bus fährt nur alle 30 Minuten. Früher bin ich meist mit dem Fahrrad gefahren, aber hier gibt es keine Fahrradwege. Und da ist ja auch noch mein Daniel, den ich morgens in den Kindergarten bringen muss. Der liegt zum Glück gleich neben meiner neuen Firma. – Wie kommst du denn zur Arbeit oder zum Deutschkurs?","Wollen wir uns nicht mal wieder treffen und alle zusammen was unternehmen? Ich würde mich freuen. Liebe Grüße Vera"],"task":"Antworten Sie Vera. Schreiben Sie etwas zu allen vier Punkte:","points":["Was es bei Ihnen Neues gibt","Was Sie zur Arbeit kommen","Was Sie über Veras neue Stelle wissen wollen","Vorschlag für gemeinsame Unternehmung?"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Vera,</strong>","tag":"Shell · Anrede","en":"Dear Vera,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Schön, dass du endlich eine neue Arbeitsstelle hast.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that you finally have a new job."},{"de":"<strong>Wie gefällt dir deine neue Arbeit? Sind deine Kollegen nett?</strong>","tag":"template, exact, kind 6 (Ask a question) · P3","en":"How do you like your new job? Are your colleagues nice?"},{"de":"Was machst du dort genau, und wie lange arbeitest du jeden Tag?","tag":"own words · P3","en":"What exactly do you do there, and how long do you work every day?"},{"de":"<strong>Bei mir gibt es Neuigkeiten: Ich lerne jetzt Deutsch, weil ich bald eine Prüfung mache.</strong>","tag":"template, exact, kind 5 (Your news) · P1","en":"I have news: I am learning German now, because I have an exam soon."},{"de":"Der Kurs ist jeden Dienstag und Donnerstag am Abend.","tag":"own words · P1","en":"The course is every Tuesday and Thursday in the evening."},{"de":"<strong>Ich komme mit dem Zug</strong> zur Arbeit.","tag":"template, start only, kind 7 (How to travel) · P2 · first sentence + zur Arbeit","en":"I come to work by train."},{"de":"Die S-Bahn fährt alle zehn Minuten, und die Fahrt dauert nur zwanzig Minuten. Zum Deutschkurs fahre ich mit dem Fahrrad.","tag":"own words · P2","en":"The S-Bahn (city train) goes every ten minutes, and the ride takes only twenty minutes. I go to the German course by bike."},{"de":"<strong>Wie wäre es, wenn wir uns am Samstag treffen? Wir könnten zusammen ins Kino gehen.</strong>","tag":"template, exact, kind 3 (Suggest a meeting) · P4","en":"How about if we meet on Saturday? We could go to the cinema together."},{"de":"Daniel kann natürlich auch mitkommen. Danach essen wir zusammen ein Eis.","tag":"own words · P4","en":"Daniel can of course come too. After that we eat an ice cream together."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":12,"title":"Jennifer","intro":"Sie haben folgenden Brief von einer Freundin erhalten:","letter":["Liebe(r) …,","Entschuldige, dass ich mich erst jetzt wieder melde. Ich weiß, wir hatten ausgemacht, uns öfter mal zu schreiben. Aber es war so viel los in letzter Zeit. Ich habe eine Neuigkeit für dich: Meine kleine Schwester Janine heiratet im Oktober, und ich habe ihr versprochen, schon mal allen Freunden zu schreiben und Bescheid zu sagen. Die offizielle Einladung bekommst du natürlich noch von ihr direkt. Eddi, ihr zukünftiger Mann, ist echt nett, und wir mögen ihn alle sehr. Er ist koch und arbeitet hier in einem Hotel. Wir planen jetzt alles. Gib mir deshalb möglichst bald Bescheid, ob du kommst und mit wem. Herzliche Grüße Jennifer"],"task":"Antworten Sie auf den Brief. Schreiben Sie etwas zu den folgenden vier Punkten:","points":["Reaktion auf Neuigkeit","Übernachtungsmöglichkeit","Sie möchten zur Hochzeit kommen","Hochzeitsgeschenk"],"hints":"Bevor Sie den Brief schreiben, überlegen Sie sich eine passende Reihenfolge der punkte, eine passende Einleitung und einen passenden Schluss. Vergessen Sie nicht Datum und Anrede.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Jennifer,</strong>","tag":"Shell · Anrede","en":"Dear Jennifer,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Was für eine tolle Nachricht! Ich freue mich sehr für Janine und Eddi.</strong>","tag":"template, adapted, kind 2 (React) · P1 · dich → Janine und Eddi","en":"What great news! I am very happy for Janine and Eddi."},{"de":"Eddi ist Koch? Dann gibt es bestimmt ein tolles Essen!","tag":"own words · P1","en":"Eddi is a cook? Then there will surely be great food!"},{"de":"<strong>Ich komme sehr gern, weil ich dich lange nicht gesehen habe.</strong>","tag":"template, exact, kind 2 (React) · P3","en":"I would love to come, because I have not seen you for a long time."},{"de":"Am Hochzeitstag haben wir zum Glück frei.","tag":"own words · P3","en":"Luckily we are free on the wedding day."},{"de":"<strong>Darf ich meine Frau mitbringen? Sie möchte dich auch gern kennenlernen.</strong>","tag":"template, exact, kind 8 (Bring someone) · P3 · with whom","en":"May I bring my wife? She would also like to meet you."},{"de":"<strong>Können wir bei dir übernachten, oder sollen wir lieber ein Hotel buchen?</strong>","tag":"template, adapted, kind 10 (Overnight stay) · P2 · ich → wir","en":"Can we stay at your place, or should we rather book a hotel?"},{"de":"Ein Hotel in der Nähe ist auch kein Problem.","tag":"own words · P2","en":"A hotel nearby is no problem either."},{"de":"Was wünschen sich Janine und Eddi zur Hochzeit? Brauchen sie vielleicht etwas für die Küche?","tag":"own words · P4 · own question","en":"What would Janine and Eddi like for the wedding? Do they maybe need something for the kitchen?"},{"de":"Ich freue mich schon sehr auf die Hochzeit. Grüß Janine bitte von mir.","tag":"own words","en":"I am really looking forward to the wedding. Please say hello to Janine from me."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":13,"title":"Andreas 2","intro":"Ein Bekannter hat Ihnen folgenden Brief geschrieben:","letter":["Liebe(r) …,","es tut mir wirklich leid, dass ich dir schon so lange nicht geschrieben habe. Bei mir ist im letzten Monat ziemlich viel los gewesen.","Vor drei Wochen bin ich nämlich in eine neue Wohnung gezogen, weil die alte für mich zu klein war. Mittlerweile habe ich mich schon sehr schön eingerichtet, mit ein paar neuen Möbeln usw. Ich fühle mich wirklich wohl! Hast du nicht Lust. Im Sommer zu mir zu Besuch zu kommen?","In meiner neuen Wohnung habe ich jetzt auch ein kleines Arbeitszimmer für meine ganzen Bücher und den Schreibtisch mit dem Computer. Wie ist das bei dir? Machst du eigentlich viel am Computer?","Lass doch mal wieder was von dir hören!","Liebe Grüße und bis bald Andreas"],"task":"Antworten Sie auf den Brief. Schreiben Sie etwas zu den folgenden vier Punkten:","points":["Ihre Erfahrungen mit dem Computer","Etwas über Ihre Wohnung","Ob Sie Andreas besuchen möchten","Was es bei Ihnen Neues gibt"],"hints":"Bevor Sie den Brief schreiben, überlegen Sie sich eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Lieber Andreas,</strong>","tag":"Shell · Anrede","en":"Dear Andreas,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Schön, dass</strong> du dich in deiner neuen Wohnung so wohlfühlst.","tag":"Shell · Schön, dass … · reaction","en":"It is nice that you feel so comfortable in your new flat."},{"de":"<strong>Bei mir gibt es Neuigkeiten: Ich lerne jetzt Deutsch, weil ich bald eine Prüfung mache.</strong>","tag":"template, exact, kind 5 (Your news) · P4","en":"I have news: I am learning German now, because I have an exam soon."},{"de":"Am Computer arbeite ich viel, denn ich bin Softwareentwickler. In meiner Freizeit benutze ich ihn aber nur wenig.","tag":"own words · P1","en":"I work at the computer a lot, because I am a software developer. In my free time, however, I use it only a little."},{"de":"<strong>Zurzeit arbeite ich als Softwareentwickler, und meine Wohnung liegt sehr zentral.</strong>","tag":"template, exact, kind 1 (About you) · P2","en":"At the moment I work as a software developer, and my flat is very central."},{"de":"Sie hat vier Zimmer, und ich fühle mich dort sehr wohl.","tag":"own words · P2","en":"It has four rooms, and I feel very comfortable there."},{"de":"<strong>Ich komme sehr gern, weil ich dich lange nicht gesehen habe.</strong>","tag":"template, exact, kind 2 (React) · P3","en":"I would love to come, because I have not seen you for a long time."},{"de":"Im August habe ich zwei Wochen Urlaub, dann könnte ich kommen.","tag":"own words · P3","en":"In August I have two weeks of holiday, then I could come."},{"de":"<strong>Kann ich bei dir übernachten, oder soll ich lieber ein Hotel buchen?</strong>","tag":"template, exact, kind 10 · P3","en":"Can I stay overnight at your place, or should I rather book a hotel?"},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":14,"title":"Thomas","intro":"Sie haben von Ihnen Freund folgende E-Mail erhalten:","letter":["Liebe(r) …,","nach unserm schönen, gemeinsamen Erlebnis letztes Jahr möchte ich auch dieses Jahr wieder einen Ausflug für uns alle organisieren. Ich hoffe sehr, dass ihr Zeit habt und mitkommen könnt - ich freue mich schon jetzt, euch alle bald wieder zu sehen! Das Dumme ist nur, dass ich mir vor drei Wochen beim Basketball das Bein gebrochen habe und noch nicht so gut zu Fuß bin. Deshalb habe ich einen gemütlichen Ausflug mit Bus und Schiff geplant - hoffentlich ist dann auch das Wetter gut für die Schiffsfahrt! Wohin es geht, möchte ich euch aber noch nicht verraten - das soll eine Überraschung werden.","Termin: übernächster Samstag.","Zeit und Treffpunkt: 9:30 Uhr bei mir.","Bitte schreibt mir doch, ob ihr beim Ausflug dabei sein könnt!","Hoffentlich bis bald.","Thomas"],"task":"Antworten Sie Thomas. Schreiben Sie etwas zu allen vier Punkten:","points":["Alternativvorschlag für Schlechtes Wetter","Einladung annehmen","Was Sie noch über den Ausflug wissen wollen","Auf Sportunfall reagieren"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Lieber Thomas,</strong>","tag":"Shell · Anrede","en":"Dear Thomas,"},{"de":"<strong>vielen Dank für deine E-Mail. Ich habe mich sehr gefreut.</strong>","tag":"template, adapted · Brief → E-Mail","en":"Many thanks for your e-mail. I was very happy."},{"de":"<strong>Es tut mir leid, dass du dir beim Basketball das Bein gebrochen hast.</strong>","tag":"template, adapted, kind 2 (React) · P4 · Es tut mir leid, dass …","en":"I am sorry that you broke your leg playing basketball."},{"de":"Hoffentlich kannst du bald wieder gut laufen.","tag":"own words · P4","en":"I hope you can walk well again soon."},{"de":"<strong>Ich komme sehr gern, weil ich dich lange nicht gesehen habe.</strong>","tag":"template, exact, kind 2 (React) · P2","en":"I would love to come, because I have not seen you for a long time."},{"de":"Übernächsten Samstag habe ich frei, und um 9:30 Uhr bin ich bei dir.","tag":"own words · P2","en":"I am free on Saturday after next, and I will be at your place at 9:30."},{"de":"Ich habe aber noch ein paar Fragen: Wann kommen wir zurück? Was kostet die Schiffsfahrt, und soll ich etwas zu essen mitbringen?","tag":"own words · P3","en":"But I still have a few questions: when do we come back? How much is the boat trip, and should I bring something to eat?"},{"de":"Und wenn das Wetter schlecht ist? Ich habe eine Idee: <strong>Wir könnten zusammen ins Kino gehen.</strong>","tag":"template, start only, kind 3 (Suggest a meeting) · P1 · second sentence exact","en":"And if the weather is bad? I have an idea: we could go to the cinema together."},{"de":"Dort musst du nicht viel laufen, und danach essen wir zusammen in einem Restaurant.","tag":"own words · P1","en":"There you do not have to walk much, and afterwards we eat together in a restaurant."},{"de":"Ich freue mich schon sehr auf den Ausflug.","tag":"own words","en":"I am really looking forward to the trip."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":15,"title":"Tamara","intro":"Eine Freundin hat Ihnen den folgenden Brief geschrieben:","letter":["Liebe(r) …,","wie geht es Dir? Du hast mir schon so lange nicht mehr geschrieben, dass ich mir Sorgen mache. Hoffentlich ist bei Euch alles in Ordnung. Es wird wirklich Zeit, dass wir uns wiedersehen.","Anfang des Jahres habe ich meinen Arbeitsplatz gewechselt. Meine neue Stelle ist sehr interessant, aber auch anstrengend.","Ich bin nun beruflich sehr viel unterwegs. Demnächst muss ich auch in Eure Gegend reisen. Dann könnten wir uns doch einmal am Abend treffen und gemeinsam etwas unternehmen. Wie findest Du meine Idee? Ich würde auch sehr gerne Deine Familie kennenlernen. Bitte antworte mir bald!","Herzliche Grüße Deine Tamara"],"task":"Antworten Sie Tamara. Schreiben Sie etwas zu allen vier Punkte:","points":["Vorschlag zum Treffen","Jemanden mitbringen","Frage zur neuen Arbeitsstelle","Warum Sie nicht geschrieben haben"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Tamara,</strong>","tag":"Shell · Anrede","en":"Dear Tamara,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Es tut mir leid, dass ich so lange nicht geschrieben habe. Ich hatte sehr viel Arbeit.</strong>","tag":"template, exact, kind 9 · P4","en":"I am sorry that I have not written for so long. I had a lot of work."},{"de":"<strong>Wie gefällt dir deine neue Arbeit? Sind deine Kollegen nett?</strong>","tag":"template, exact, kind 6 (Ask a question) · P3","en":"How do you like your new job? Are your colleagues nice?"},{"de":"Du bist jetzt viel unterwegs. Ist das nicht sehr anstrengend?","tag":"own words · P3","en":"You are travelling a lot now. Is that not very tiring?"},{"de":"<strong>Wie wäre es, wenn wir</strong> uns am Abend zum Essen treffen? Wir könnten ein italienisches Restaurant besuchen.","tag":"template start + own words · kind 3 (Suggest) · P1","en":"How about we meet for dinner in the evening? We could go to an Italian restaurant."},{"de":"Sag mir bitte, an welchem Abend du Zeit hast.","tag":"own words · P1","en":"Please tell me on which evening you have time."},{"de":"Zurzeit arbeite ich viel, aber jetzt habe ich endlich Zeit zum Schreiben.","tag":"own words · P4","en":"At the moment I work a lot, but now I finally have time to write."},{"de":"<strong>Darf ich meine Frau mitbringen? Sie möchte dich auch gern kennenlernen.</strong>","tag":"template, exact, kind 8 · P2","en":"May I bring my wife? She would also like to get to know you."},{"de":"Du wolltest ja meine Familie kennenlernen, und meine Kinder freuen sich schon.","tag":"own words · P2","en":"You wanted to meet my family, after all, and my children are already looking forward to it."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":16,"title":"Jan","intro":"Ihr Freund Jan hat Ihnen folgende E-Mail geschrieben:","letter":["Liebe(r) …,","Ich sende Dir ganz viele Grüße aus Rom! Du weißt ja, wie sehr mir diese Stadt gefällt. Ich bin hier von morgens bis abends nur unterwegs. Diese Museen, Parks Plätze und natürlich das Essen – wunderbar! Gestern Abend war ich übrigens in einem Rockkonzert. Ich fand die Musik ganz toll und die Stimmung war super.","Doch Leider ist mein Urlaub schon fast vorbei und in drei Tagen muss ich wieder zurück nach Deutschland. Welche Stadt ist eigentlich Deine Lieblingsstadt? Hast du schon Pläne für Deinen nächsten Urlaub? Vielleicht können wir uns ja mal wieder treffen.","Herzliche Grüße Jan"],"task":"Antworten Sie Jan. Schreiben Sie etwas zu allen vier Punkte:","points":["Ihre Lieblingsstadt","Welche Musik Sie mögen","Ihre Pläne für den nächsten Urlaub","Treffen mit Jan?"],"hints":"Überlegen Sie sich vor dem Schreiben eine passende Reihenfolge der punkte, eine passende Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Lieber Jan,</strong>","tag":"Shell · Anrede","en":"Dear Jan,"},{"de":"<strong>vielen Dank für deine E-Mail. Ich habe mich sehr gefreut.</strong>","tag":"template, adapted · Brief → E-Mail","en":"Many thanks for your e-mail. I was very happy."},{"de":"<strong>Schön, dass dir dein Urlaub in Rom so gut gefällt.</strong>","tag":"Shell · Schön, dass …","en":"It is nice that you like your holiday in Rome so much."},{"de":"<strong>Zurzeit arbeite ich als Softwareentwickler, und meine Wohnung liegt sehr zentral.</strong>","tag":"template, exact, kind 1 (About you) · P1","en":"At the moment I work as a software developer, and my flat is very central."},{"de":"Meine Lieblingsstadt ist München, weil ich von meiner Wohnung schnell in die Altstadt und in die Parks komme.","tag":"own words · P1","en":"My favourite city is Munich, because from my flat I can quickly get to the old town and the parks."},{"de":"Ich mag Popmusik und auch Musik aus Pakistan. Rockmusik höre ich nicht so oft, aber ein Konzert finde ich toll.","tag":"own words · P2","en":"I like pop music and also music from Pakistan. I do not listen to rock music very often, but I think a concert is great."},{"de":"Im nächsten Urlaub fahre ich mit meiner Frau in die Berge. Dort möchten wir wandern und uns gut erholen.","tag":"own words · P3","en":"On my next holiday I am going to the mountains with my wife. There we want to go hiking and have a good rest."},{"de":"<strong>Wie wäre es, wenn wir uns am Samstag treffen? Wir könnten zusammen ins Kino gehen.</strong>","tag":"template, exact, kind 3 (Suggest a meeting) · P4","en":"How about if we meet on Saturday? We could go to the cinema together."},{"de":"Dann kannst du mir von Rom erzählen und mir deine Fotos zeigen.","tag":"own words · P4","en":"Then you can tell me about Rome and show me your photos."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":17,"title":"Viktor","intro":"Ihr Freund Viktor hat Ihnen folgenden Brief geschrieben:","letter":["Liebe(r) …,","ich sende dir sonnige Grüße von der wunderschönen Insel Malta! Katja, die Kinder und ich sind ganz glücklich! Strand, Kultur, Sport – all das ist hier möglich! Gestern haben wir uns sogar ein Auto gemietet und einen Ausflug gemacht. Und auch für mein Hobby, das Fotografieren, habe ich sehr viel Zeit, ich habe schon ganz viele Fotos gemacht. Ich schicke dir mit diesem Brief auch ein Buch über Malta, damit du siehst, wie interessant dieses Land ist. Hoffentlich gefällt dir das Buch. Leider ist unser Urlaub auch schon in wenigen Tagen vorbei. Wie wäre das – vielleicht können wir uns ja wieder einmal treffen?","Bis hoffentlich bald, Viktor"],"task":"Antworten Sie auf diesen Brief. Schreiben Sie in Ihrem Brief etwas zu den folgenden vier Punkten:","points":["Ihre Hobbys","Reaktion auf das Buch","Ihre Pläne für den nächsten Urlaub","Treffen mit Viktor"],"hints":"Bevor Sie den Brief schreiben, überlegen Sie sich eine passende Reihenfolge der Punkte, einen passenden Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Lieber Viktor,</strong>","tag":"Shell · Anrede","en":"Dear Viktor,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Schön, dass</strong> ihr einen so tollen Urlaub auf Malta habt.","tag":"Shell · Schön, dass …","en":"It is nice that you are having such a great holiday in Malta."},{"de":"Das Buch über Malta gefällt mir sehr. Die Fotos sind wunderschön, und ich möchte die Insel auch gern einmal sehen.","tag":"own words · P2","en":"I like the book about Malta very much. The photos are beautiful, and I would also like to see the island one day."},{"de":"<strong>Am Wochenende koche ich gern für meine Familie.</strong>","tag":"template, exact, kind 1 (About you) · P1","en":"At the weekend I like cooking for my family."},{"de":"Außerdem gehe ich jeden Tag spazieren und spiele manchmal Cricket.","tag":"own words · P1","en":"I also go for a walk every day and sometimes play cricket."},{"de":"Im Sommer möchte ich mit meiner Familie nach Italien fahren. Wir wollen vor allem am Meer sein.","tag":"own words · P3","en":"In summer I would like to go to Italy with my family. We mainly want to be by the sea."},{"de":"Dort können wir schwimmen gehen und abends zusammen essen.","tag":"own words · P3","en":"There we can go swimming and have dinner together in the evening."},{"de":"Ich wünsche euch noch ein paar schöne, sonnige Tage.","tag":"own words · closing thought","en":"I wish you a few more lovely, sunny days."},{"de":"<strong>Wie wäre es, wenn wir</strong> uns nach deinem Urlaub treffen? Wir könnten zusammen essen gehen.","tag":"template start + own words · kind 3 (Suggest) · P4","en":"How about we meet after your holiday? We could go for a meal together."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]},{"no":18,"title":"Rita","intro":"Eine Bekannte hat Ihnen folgenden Brief geschrieben:","letter":["Liebe(r) …,","endlich habe ich Zeit, dir wieder mal zu schreiben. Schade, dass du bei unserer Hochzeit nicht dabei sein konntest! Wir waren mit Freunden und Verwandten über 50 Personen. Ich habe ein langes, weißes Kleid getragen, und Karl hat sich für diesen Tag einen teuren, schwarzen Anzug gekauft, obwohl er sonst immer nur Jeans trägt. Natürlich gab es ein wunderbares Festessen und danach wurde getanzt. Karl und ich haben viele Geschenke bekommen, vor allem auch Geld für unsere Hochzeitsreise. Wir wissen aber noch gar nicht, wohin wir fahren wollen.","Wie läuft’s eigentlich bei dir, du hast doch eine neue Stelle? Wie gefällt dir die Arbeit? Karl und ich würden uns sehr freuen, wenn du uns wieder mal besuchen würdest!","Liebe Grüße","Rita"],"task":"Antworten Sie Ihrer Bekannten. Schreiben Sie etwas zu den folgenden vier Punkten:","points":["Ihre neue Arbeitsstelle","Wie man in Ihrem Land heiratet","Vorschlag für Ritas Hochzeitsreise","Rita und Karl besuchen?"],"hints":"Bevor Sie den Brief schreiben, überlegen Sie sich eine passende Reihenfolge der Punkte, einen passenden Betreff, eine passende Anrede, Einleitung und einen passenden Schluss.","sol":[{"de":"<strong>München, 31.10.2026</strong>","tag":"Shell · place and date","en":"Munich, 31 October 2026"},{"de":"<strong>Liebe Rita,</strong>","tag":"Shell · Anrede","en":"Dear Rita,"},{"de":"<strong>vielen Dank für deinen Brief. Ich habe mich sehr gefreut.</strong>","tag":"Shell · thank-you line","en":"Many thanks for your letter. I was very happy."},{"de":"<strong>Es tut mir leid, dass</strong> ich bei eurer Hochzeit nicht dabei sein konnte.","tag":"Shell · Es tut mir leid, dass …","en":"I am sorry that I could not be at your wedding."},{"de":"Meine neue Stelle gefällt mir gut. Meine Kollegen sind nett, und die Arbeit macht mir Spaß.","tag":"own words · P1","en":"I like my new job. My colleagues are nice, and I enjoy the work."},{"de":"Besonders gefällt mir, dass ich jeden Tag etwas Neues lerne.","tag":"own words · P1","en":"I especially like that I learn something new every day."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"family 2, home country, exact · P2","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Ich schlage vor, dass</strong> ihr nach Italien fahrt. Dort ist es im Sommer schön warm, und ihr könnt am Meer entspannen.","tag":"Shell · Ich schlage vor, dass … · P3","en":"I suggest that you go to Italy. It is nicely warm there in summer, and you can relax by the sea."},{"de":"<strong>Ich komme sehr gern, weil ich dich lange nicht gesehen habe.</strong>","tag":"template, exact, kind 2 (React) · P4","en":"I would love to come, because I have not seen you for a long time."},{"de":"Schreibt mir bitte, wann ihr Zeit habt.","tag":"own words · P4","en":"Please write to me when you have time."},{"de":"Ich bin sehr gespannt auf eure Hochzeitsfotos.","tag":"own words · closing thought","en":"I am very curious about your wedding photos."},{"de":"<strong>Lass bald wieder von dir hören.</strong>","tag":"Shell · closing line","en":"Let me hear from you again soon."},{"de":"<strong>Viele Grüße / [dein Name]</strong>","tag":"Shell · greeting + your name","en":"Best wishes / [your name]"}]}];
